import "server-only";
import { db } from "@/lib/db";
import { inngest } from "@/lib/inngest-client";
import {
  expireDeletionCredentials,
  prepareDeletionJob,
  runDeletionJob,
} from "@/lib/deletion-jobs";

export const deletionJobSweep = inngest.createFunction(
  {
    id: "account-deletion-jobs",
    triggers: { cron: "0 2 * * *" },
    concurrency: 1,
  },
  async ({ step }) => {
    await step.run("expire-credentials", () => expireDeletionCredentials());
    // Prepare legacy requests first; only the job scan publishes work, once per owner.
    let cursor: string | undefined;
    for (let page = 0; ; page++) {
      const ids = await step.run(`legacy-${page}`, async () => {
        const rows = await db.user.findMany({
          where: {
            deletionRequestedAt: { not: null },
            ...(cursor ? { id: { gt: cursor } } : {}),
          },
          select: { id: true },
          orderBy: { id: "asc" },
          take: 50,
        });
        for (const { id } of rows) await prepareDeletionJob(id);
        return rows;
      });
      if (ids.length < 50) break;
      cursor = ids.at(-1)!.id;
    }
    cursor = undefined;
    for (let page = 0; ; page++) {
      const jobs = await step.run(`jobs-${page}`, () =>
        db.accountDeletionJob.findMany({
          where: {
            completedAt: null,
            nextAttemptAt: { lte: new Date() },
            ...(cursor ? { id: { gt: cursor } } : {}),
          },
          select: { id: true, userId: true },
          orderBy: { id: "asc" },
          take: 50,
        }),
      );
      if (jobs.length)
        await step.sendEvent(
          `dispatch-${page}`,
          jobs.map(({ userId }) => ({
            name: "mailloop/account.deletion",
            data: { userId },
          })),
        );
      if (jobs.length < 50) break;
      cursor = jobs.at(-1)!.id;
    }
  },
);

import { z } from "zod";
export const deletionJobWorker = inngest.createFunction(
  {
    id: "account-deletion-worker",
    triggers: { event: "mailloop/account.deletion" },
    concurrency: { limit: 1, key: "event.data.userId" },
  },
  ({ event, step }) => {
    const { userId } = z.object({ userId: z.uuid() }).parse(event.data);
    return step.run("process-deletion", () => runDeletionJob(userId));
  },
);
